  ""

const PROVIA_100F_BASE64 =
  ""

const VIVID_50_BASE64 =
  ""

export function getBundledLutBytes(id: string): Uint8Array | null {
  if (id === "bali-400-v1") {
    return new Uint8Array(Buffer.from(BALI_400_BASE64, "base64"))
  }
  if (id === "martha-v1") {
    return new Uint8Array(Buffer.from(MARTHA_BASE64, "base64"))
  }
  if (id === "momints-aura-400") {
    return new Uint8Array(Buffer.from(AURA_400_BASE64, "base64"))
  }
  if (id === "momints-amber-200") {
    return new Uint8Array(Buffer.from(AMBER_200_BASE64, "base64"))
  }
  if (id === "momints-silver-400") {
    return new Uint8Array(Buffer.from(SILVER_400_BASE64, "base64"))
  }
  if (id === "momints-neon-800t") {
    return new Uint8Array(Buffer.from(NEON_800T_BASE64, "base64"))
  }
  if (id === "momints-chrome-64") {
    return new Uint8Array(Buffer.from(CHROME_64_BASE64, "base64"))
  }
  if (id === "momints-ektar-100") {
    return new Uint8Array(Buffer.from(EKTAR_100_BASE64, "base64"))
  }
  if (id === "momints-hp5-plus") {
    return new Uint8Array(Buffer.from(HP5_PLUS_BASE64, "base64"))
  }
  if (id === "momints-lomo-purple") {
    return new Uint8Array(Buffer.from(LOMO_PURPLE_BASE64, "base64"))
  }
  if (id === "momints-provia-100f") {
    return new Uint8Array(Buffer.from(PROVIA_100F_BASE64, "base64"))
  }
  if (id === "momints-vivid-50") {
    return new Uint8Array(Buffer.from(VIVID_50_BASE64, "base64"))
  }
  return null
}
